export type WorkshopMessageKey = keyof typeof messages
type WorkshopCatalog = Record<WorkshopMessageKey, string>

const catalogs = Object.fromEntries(
  LOCALES.map((locale, index) => [
    locale,
    Object.fromEntries(Object.entries(messages).map(([key, values]) => [key, values[index]!])),
  ]),
) as Record<UiLocale, WorkshopCatalog>

